  id: string
  type: PageModuleType
  version: number
  slot: 'HERO' | 'RESULT' | 'CONTENT' | 'FLOATING'
  propsJson: string
}

type JoinInteraction =
  | { mode: 'DIRECT'; command: 'LOTTERY_JOIN' }
  | {
      mode: 'SELECT_SESSION'
      command: 'LOTTERY_JOIN'
      title: string
      agreement: Agreement
      options: JoinSessionOption[]
    }

type ActivityPageResponse = {
  response: {
    success: boolean
    code: number
    msg: string
  }
  data?: PageDocument
}

type PageDocument = {
  activityId: string
  activityType: 'LOTTERY' | 'POINTS_EXCHANGE' | 'FREE_EXCHANGE'
  protocolVersion: '1.0'
  configVersion: number
  sceneCode: string
  serverTime: number
  refreshAfterMs?: number
  schedule: ActivitySchedule
  page: {
    theme: ActivityTheme
    modules: PageModule[]
    footer: RenderActionGroup | null
    interactions: {
      join: JoinInteraction
    }
  }
  runtime: ActivityRuntime
}
